// Thin wrapper around the OpenNext-generated worker that adds Cloudflare Cron Trigger
// support. .open-next/worker.js is fully regenerated by `npm run build:cf`, so this file
// (not that one) is what wrangler.toml points `main` at — it survives rebuilds.
import openNextWorker, { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

export { DOQueueHandler, DOShardedTagCache, BucketCachePurge };

// Maps the exact cron string (from wrangler.toml [triggers]) to the internal route it runs.
const CRON_ROUTES = {
  "17 * * * *": "/api/cron/refresh-recalls",       // hourly; each run handles a batch of models
  "40 2 * * *": "/api/cron/sync-israeli-recalls",  // daily, data.gov.il manufacturer notices
  "0 6 * * *": "/api/cron/refresh-news",
  "30 11 * * *": "/api/cron/refresh-news?mode=retry", // retry recent untranslated news with Gemini
  "30 17 * * *": "/api/cron/refresh-news?mode=retry",
};

// One `cron_runs` row per dispatch with the HTTP status the job route returned, so a
// job that never ran (e.g. 401 because CRON_SECRET is missing) is visible in the data.
async function recordDispatch(env, cron, path, status, ok, note) {
  try {
    await env.DB.prepare(
      `INSERT INTO cron_runs (job, trigger, started_at, finished_at, status, http_status, detail)
       VALUES (?, ?, datetime('now'), datetime('now'), ?, ?, ?)`,
    ).bind(`dispatch:${path}`, cron, ok ? "ok" : "failed", status, JSON.stringify({ note: note || null, cronSecretSet: !!env.CRON_SECRET })).run();
  } catch (err) {
    console.error("[cron dispatch] could not record run", err);
  }
}

// ── Page-view log (internal analytics, D1 page_visits) ──────────────────────
// Logs human HTML page views only: GET document requests, no /api, /_next, files or bots.
// Written in ctx.waitUntil so it never delays the response; failures are swallowed.
const VISIT_RETENTION_DAYS = 90;
const VISIT_BOT_UA = /bot|crawl|spider|slurp|headless|lighthouse|pagespeed|preview|facebookexternalhit|whatsapp|telegram|curl|wget|python|go-http|axios|node-fetch|httpclient|java\/|monitor|uptime|lightpanda|carissues-qa/i;
const VISIT_HOSTS = /(^|\.)carissues\.(co\.il|net)$/;

// Scrapers that send a normal-looking browser user agent (measured 2026-11-12: ~95% of
// logged rows). Three signals, each checked against the rows already in page_visits:
// 1. Hosting / proxy networks the swarm came from. Real visitors do not browse from these.
//    Google's 15169 is deliberately absent: Israeli Chrome users arrive through it.
const VISIT_BOT_ASNS = new Set([
  214483, // RapidSeedbox
  132203, // Tencent / Aceville ("6 Collyer Quay")
  45090,  // Tencent Cloud
  136907, 55990, // Huawei Cloud
  45102,  // Alibaba Cloud
  62610,  // MB Eisina / Pilo IP / Nuba IP
  35758,  // Brander Group (proxy IPs that geolocate to Israel)
  396982, // Google Cloud (our own QA browsers run here too)
  14061, 51167, 24940, 16276, 63949, 20473, // DigitalOcean, Contabo, Hetzner, OVH, Linode, Vultr
]);
// 2. Desktop browsers auto-update, so a desktop Chrome/Firefox this old is a canned bot
//    string. Floors are far behind current (Chrome 157 in Nov 2026); raise them once a year.
//    Phones are exempt: old Android devices really do run old Chrome.
const MIN_DESKTOP_CHROME = 135;
const MIN_DESKTOP_FIREFOX = 128;
// 3. One fixed iPhone string used by the swarm (iOS 13.2.3, released 2019).
const VISIT_FAKE_UA = /iPhone OS 13_2_3 /;

function isDisguisedBot(request, ua) {
  const asn = request.cf && request.cf.asn;
  if (asn && VISIT_BOT_ASNS.has(asn)) return true;
  if (VISIT_FAKE_UA.test(ua)) return true;
  // Every real browser sends Accept-Language on a page load
  if (!request.headers.get("accept-language")) return true;
  if (/Windows NT|Macintosh|X11/.test(ua)) {
    const chrome = ua.match(/Chrome\/(\d+)/);
    if (chrome && Number(chrome[1]) < MIN_DESKTOP_CHROME) return true;
    const firefox = ua.match(/Firefox\/(\d+)/);
    if (firefox && Number(firefox[1]) < MIN_DESKTOP_FIREFOX) return true;
  }
  // Chromium has sent Sec-Fetch-Dest on navigations since v80; HTTP libraries faking a
  // Chrome user agent usually do not.
  if (/Chrome\//.test(ua) && !request.headers.get("sec-fetch-dest")) return true;
  return false;
}

function parseUa(ua) {
  const device = /ipad|tablet/i.test(ua) ? "tablet" : /mobi|iphone|android/i.test(ua) ? "mobile" : "desktop";
  const os = /iphone|ipad|ios/i.test(ua) ? "iOS"
    : /android/i.test(ua) ? "Android"
    : /windows/i.test(ua) ? "Windows"
    : /mac os x|macintosh/i.test(ua) ? "macOS"
    : /linux/i.test(ua) ? "Linux" : "other";
  const browser = /edg\//i.test(ua) ? "Edge"
    : /samsungbrowser/i.test(ua) ? "Samsung Internet"
    : /opr\/|opera/i.test(ua) ? "Opera"
    : /firefox|fxios/i.test(ua) ? "Firefox"
    : /crios|chrome/i.test(ua) ? "Chrome"
    : /safari/i.test(ua) ? "Safari" : "other";
  return { device, os, browser };
}

function shouldLogVisit(request, url, response) {
  if (request.method !== "GET") return false;
  if (!VISIT_HOSTS.test(url.hostname)) return false;
  const p = url.pathname;
  if (p.startsWith("/api/") || p.startsWith("/_next/") || p.startsWith("/cdn-cgi/")) return false;
  if (/\.[a-z0-9]{2,5}$/i.test(p)) return false; // files: .png, .xml, .txt, ...
  const dest = request.headers.get("sec-fetch-dest");
  if (dest && dest !== "document") return false;
  if (!dest && !(request.headers.get("accept") || "").includes("text/html")) return false;
  if (request.headers.get("rsc") || request.headers.get("next-router-prefetch")) return false;
  const ua = request.headers.get("user-agent") || "";
  if (!ua || VISIT_BOT_UA.test(ua) || isDisguisedBot(request, ua)) return false;
  // Redirects (www → apex, geo) would double-count; keep real pages and 404s
  return response.status < 300 || response.status === 404;
}

async function logVisit(env, request, url) {
  try {
    const cf = request.cf || {};
    const ua = request.headers.get("user-agent") || "";
    const { device, os, browser } = parseUa(ua);
    await env.DB.prepare(
      `INSERT INTO page_visits
        (ip, site, path, query, referer, country, region, city, postal_code, latitude, longitude,
         timezone, asn, asn_org, device, os, browser, user_agent, lang)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    ).bind(
      request.headers.get("cf-connecting-ip"),
      url.hostname.includes("carissues.net") ? "en" : "he",
      url.pathname.slice(0, 500),
      url.search ? url.search.slice(0, 500) : null,
      (request.headers.get("referer") || "").slice(0, 300) || null,
      cf.country ?? null, cf.region ?? null, cf.city ?? null, cf.postalCode ?? null,
      cf.latitude ?? null, cf.longitude ?? null, cf.timezone ?? null,
      cf.asn ?? null, cf.asOrganization ?? null,
      device, os, browser, ua.slice(0, 400),
      (request.headers.get("accept-language") || "").slice(0, 40) || null,
    ).run();
    if (Math.random() < 0.005) {
      await env.DB.prepare(`DELETE FROM page_visits WHERE created_at < datetime('now', ?)`)
        .bind(`-${VISIT_RETENTION_DAYS} days`).run();
    }
  } catch (err) {
    console.error("[page_visits] log failed", err);
  }
}

// ── Edge HTML cache ──────────────────────────────────────────────────────────
// The root layout reads headers() (host -> he/en), so Next renders every page on every
// request and `revalidate` never applies. Rendered HTML depends only on host + path, so
// cache it here in the per-colo Cache API, keyed by the full URL (host included).
// Only plain document GETs on the canonical hosts with no query string are cached, and
// requests that middleware would treat differently bypass it: the `clang` preference
// cookie (cross-host redirects) and carissues.net/ (geo redirect for Israel).
// Trade-off: a page can be up to EDGE_HTML_TTL_SEC stale (e.g. a new review).
const EDGE_HTML_TTL_SEC = 3 * 60 * 60;
const EDGE_CACHE_HOSTS = new Set(["carissues.co.il", "carissues.net"]);

function isEdgeCacheable(request, url) {
  if (request.method !== "GET") return false;
  if (!EDGE_CACHE_HOSTS.has(url.hostname)) return false;
  if (url.search) return false;
  const p = url.pathname;
  if (p.startsWith("/api/") || p.startsWith("/_next/") || p.startsWith("/admin") || p.startsWith("/cdn-cgi/")) return false;
  if (url.hostname === "carissues.net" && p === "/") return false;
  if (!(request.headers.get("accept") || "").includes("text/html")) return false;
  if (request.headers.get("rsc") || request.headers.get("next-router-prefetch") || request.headers.get("next-router-state-tree")) return false;
  if (request.headers.get("authorization")) return false;
  if (/(^|;\s*)clang=/.test(request.headers.get("cookie") || "")) return false;
  return true;
}

async function renderWithEdgeCache(request, env, ctx, url) {
  const cache = caches.default;
  const key = new Request(`https://${url.hostname}${url.pathname}`, { method: "GET" });
  const hit = await cache.match(key);
  if (hit) {
    const res = new Response(hit.body, hit);
    res.headers.set("cache-control", "private, no-cache, no-store, max-age=0, must-revalidate");
    res.headers.set("x-edge-cache", "HIT");
    return res;
  }
  const response = await openNextWorker.fetch(request, env, ctx);
  const type = response.headers.get("content-type") || "";
  if (response.status === 200 && type.includes("text/html") && !response.headers.has("set-cookie")) {
    const toStore = new Response(response.clone().body, response);
    toStore.headers.set("cache-control", `public, s-maxage=${EDGE_HTML_TTL_SEC}`);
    ctx.waitUntil(cache.put(key, toStore).catch((err) => console.error("[edge cache] put failed", err)));
  }
  const res = new Response(response.body, response);
  res.headers.set("x-edge-cache", "MISS");
  return res;
}

export default {
  async fetch(request, env, ctx) {
    let response;
    try {
      const url = new URL(request.url);
      response = isEdgeCacheable(request, url)
        ? await renderWithEdgeCache(request, env, ctx, url)
        : await openNextWorker.fetch(request, env, ctx);
    } catch (err) {
      console.error("[edge cache] falling back to direct render", err);
      response = await openNextWorker.fetch(request, env, ctx);
    }
    try {
      const url = new URL(request.url);
      if (shouldLogVisit(request, url, response)) ctx.waitUntil(logVisit(env, request, url));
    } catch { /* never let logging break a page */ }
    return response;
  },
  async scheduled(event, env, ctx) {
    const path = CRON_ROUTES[event.cron];
    if (!path) {
      console.error("[cron dispatch] no route for cron", event.cron);
      return;
    }
    const req = new Request(`https://carissues.co.il${path}`, {
      headers: { Authorization: `Bearer ${env.CRON_SECRET}`, "x-cron-trigger": event.cron },
    });
    ctx.waitUntil((async () => {
      try {
        const res = await openNextWorker.fetch(req, env, ctx);
        const body = await res.text().catch(() => "");
        if (!res.ok) console.error(`[cron dispatch] ${path} -> HTTP ${res.status}`, body.slice(0, 500));
        await recordDispatch(env, event.cron, path, res.status, res.ok, res.ok ? null : body.slice(0, 500));
      } catch (err) {
        console.error(`[cron dispatch] ${path} threw`, err);
        await recordDispatch(env, event.cron, path, null, false, String(err).slice(0, 500));
      }
    })());
  },
};
